package dev.zain.znkeyboard

import java.util.Locale

// Generated from Unicode Emoji 17.0 emoji-test.txt (2025-08-04).
// Source: https://www.unicode.org/Public/17.0.0/emoji/emoji-test.txt
enum class EmojiCategory(val title: String, val icon: String) {
    SmileysEmotion("Smileys & Emotion", "😀"),
    PeopleBody("People & Body", "👋"),
    AnimalsNature("Animals & Nature", "🐻"),
    FoodDrink("Food & Drink", "🍔"),
    TravelPlaces("Travel & Places", "✈️"),
    Activities("Activities", "⚽"),
    Objects("Objects", "💡"),
    Symbols("Symbols", "🔣"),
    Flags("Flags", "🏳️"),
}

enum class EmojiSkinTone(
    val id: String,
    val label: String,
    val sample: String,
    val modifier: String,
) {
    Default("default", "Default", "👍", ""),
    Light("light", "Light", "👍🏻", "🏻"),
    MediumLight("medium_light", "Medium-light", "👍🏼", "🏼"),
    Medium("medium", "Medium", "👍🏽", "🏽"),
    MediumDark("medium_dark", "Medium-dark", "👍🏾", "🏾"),
    Dark("dark", "Dark", "👍🏿", "🏿"),
}

data class EmojiEntry(
    val emoji: String,
    val name: String,
    val category: EmojiCategory,
    val subgroup: String,
    val baseEmoji: String = emoji,
    val skinTone: EmojiSkinTone = EmojiSkinTone.Default,
) {
    val baseName: String = name.substringBefore(": ")
    val searchText: String = listOf(name, baseName, category.title, subgroup.replace('-', ' ')).joinToString(" ")
        .lowercase(Locale.US)
}

object EmojiCatalog {
    const val DEFAULT_RECENT_ROW_COUNT = 3
    const val MIN_RECENT_ROW_COUNT = 1
    const val MAX_RECENT_ROW_COUNT = 6
    const val RECENT_COLUMN_COUNT = 8
    const val MAX_STORED_RECENT_EMOJIS = MAX_RECENT_ROW_COUNT * RECENT_COLUMN_COUNT
    private const val MAX_SEARCH_RESULTS = 240

    val categories: List<EmojiCategory> = EmojiCategory.entries

    val entries: List<EmojiEntry> by lazy(LazyThreadSafetyMode.PUBLICATION) {
        buildList {
            addVisibleEntries0()
            addVisibleEntries1()
            addVisibleEntries2()
            addVisibleEntries3()
            addVisibleEntries4()
            addVisibleEntries5()
            addVisibleEntries6()
            addVisibleEntries7()
            addVisibleEntries8()
            addVisibleEntries9()
            addVisibleEntries10()
        }
    }

    private val allEntries: List<EmojiEntry> by lazy(LazyThreadSafetyMode.PUBLICATION) {
        buildList {
            addAllEntries0()
            addAllEntries1()
            addAllEntries2()
            addAllEntries3()
            addAllEntries4()
            addAllEntries5()
            addAllEntries6()
            addAllEntries7()
            addAllEntries8()
            addAllEntries9()
            addAllEntries10()
            addAllEntries11()
            addAllEntries12()
            addAllEntries13()
            addAllEntries14()
            addAllEntries15()
            addAllEntries16()
            addAllEntries17()
            addAllEntries18()
            addAllEntries19()
            addAllEntries20()
            addAllEntries21()
        }
    }

    val entriesByCategory: Map<EmojiCategory, List<EmojiEntry>> by lazy(LazyThreadSafetyMode.PUBLICATION) {
        entries.groupBy { it.category }
    }

    private val supportedEmoji: Set<String> by lazy(LazyThreadSafetyMode.PUBLICATION) {
        allEntries.mapTo(mutableSetOf()) { it.emoji }
    }

    private val entriesByEmoji: Map<String, EmojiEntry> by lazy(LazyThreadSafetyMode.PUBLICATION) {
        allEntries.associateBy { it.emoji }
    }

    private val variantsByBaseEmoji: Map<String, List<EmojiEntry>> by lazy(LazyThreadSafetyMode.PUBLICATION) {
        allEntries
            .filter { it.skinTone != EmojiSkinTone.Default }
            .groupBy { it.baseEmoji }
            .mapValues { (_, variants) ->
                variants.sortedBy { it.skinTone.ordinal }
            }
    }

    fun isSupportedEmoji(emoji: String): Boolean = emoji in supportedEmoji

    fun entryForEmoji(emoji: String): EmojiEntry? = entriesByEmoji[emoji]

    fun displayEmoji(entry: EmojiEntry, skinTone: EmojiSkinTone): String {
        if (entry.skinTone != EmojiSkinTone.Default || skinTone == EmojiSkinTone.Default) return entry.emoji
        return variantsByBaseEmoji[entry.baseEmoji]
            ?.firstOrNull { it.skinTone == skinTone }
            ?.emoji
            ?: entry.emoji
    }

    fun variantsFor(entry: EmojiEntry): List<EmojiEntry> {
        val base = entriesByEmoji[entry.baseEmoji] ?: entry
        val variants = variantsByBaseEmoji[base.emoji].orEmpty()
        return if (variants.isEmpty()) emptyList() else listOf(base) + variants
    }

    fun normalizeRecentRowCount(rowCount: Int): Int {
        return rowCount.coerceIn(MIN_RECENT_ROW_COUNT, MAX_RECENT_ROW_COUNT)
    }

    fun normalizeRecentEmojis(
        emojis: List<String>,
        maxCount: Int = MAX_STORED_RECENT_EMOJIS,
    ): List<String> {
        return emojis
            .map { it.trim() }
            .filter { it.isNotEmpty() && isSupportedEmoji(it) }
            .distinct()
            .take(maxCount.coerceIn(RECENT_COLUMN_COUNT, MAX_STORED_RECENT_EMOJIS))
    }

    fun promoteRecentEmoji(emoji: String, current: List<String>): List<String> {
        if (!isSupportedEmoji(emoji)) return normalizeRecentEmojis(current)
        return normalizeRecentEmojis(listOf(emoji) + current.filterNot { it == emoji })
    }

    fun search(
        query: String,
        customTagsByEmoji: Map<String, List<String>> = emptyMap(),
    ): List<EmojiEntry> {
        val terms = query
            .trim()
            .lowercase(Locale.US)
            .split(Regex("\\s+"))
            .filter { it.isNotBlank() }
        if (terms.isEmpty()) return emptyList()

        val customSearchTextByEmoji = customTagsByEmoji
            .mapNotNull { (emoji, tags) ->
                val supportedEmoji = entryForEmoji(emoji)?.emoji ?: return@mapNotNull null
                val searchText = tags.joinToString(" ")
                    .lowercase(Locale.US)
                    .takeIf { it.isNotBlank() }
                    ?: return@mapNotNull null
                supportedEmoji to searchText
            }
            .toMap()
        val customTaggedEntries = if (customSearchTextByEmoji.isEmpty()) {
            emptySequence()
        } else {
            allEntries
                .asSequence()
                .filter { it.emoji in customSearchTextByEmoji }
        }
        val source = if (terms.any { it in skinToneSearchTerms }) {
            entries.asSequence() + allEntries.asSequence().filter { it.skinTone != EmojiSkinTone.Default }
        } else {
            entries.asSequence()
        } + customTaggedEntries

        return source
            .filter { entry -> entry.matchesSearchTerms(terms, customSearchTextByEmoji) }
            .distinctBy { it.emoji }
            .take(MAX_SEARCH_RESULTS)
            .toList()
    }

    private fun EmojiEntry.matchesSearchTerms(
        terms: List<String>,
        customSearchTextByEmoji: Map<String, String>,
    ): Boolean {
        val customSearchText = customSearchTextByEmoji[emoji].orEmpty()
        return terms.all { term ->
            term in searchText || term in customSearchText
        }
    }

    private val skinToneSearchTerms = setOf(
        "skin",
        "tone",
        "light",
        "medium",
        "dark",
        "medium-light",
        "medium-dark",
    )

